func (this *Button) UpdateSelection(flags int32) {
	if int64(flags) != win32.OSSendMessageOverload4(this.Handle, win32.OSBM_GETCHECK, int64(0), int64(0)) {
		var bits int32 = win32.OSGetWindowLong(this.Handle, win32.OSGWL_STYLE)
		if (this.style & CHECK) != 0 {
			if flags == win32.OSBST_INDETERMINATE {
				bits &= ^win32.OSBS_CHECKBOX
				bits |= win32.OSBS_3STATE
			} else {
				bits |= win32.OSBS_CHECKBOX
				bits &= ^win32.OSBS_3STATE
			}
			if bits != win32.OSGetWindowLong(this.Handle, win32.OSGWL_STYLE) {
				win32.OSSetWindowLong(this.Handle, win32.OSGWL_STYLE, bits)
			}
		}
		win32.OSSendMessageOverload4(this.Handle, win32.OSBM_SETCHECK, int64(flags), int64(0))
		if bits != win32.OSGetWindowLong(this.Handle, win32.OSGWL_STYLE) {
			win32.OSSetWindowLong(this.Handle, win32.OSGWL_STYLE, bits)
		}
	}
}

func (this *Button) widgetStyle_() int32 {
	var bits int32 = this.Control.widgetStyle_()
	if (this.style & FLAT) != 0 {
		bits |= win32.OSBS_FLAT
	}
	if (this.style & ARROW) != 0 {
		return bits | win32.OSBS_OWNERDRAW
	}
	if (this.style & LEFT) != 0 {
		bits |= win32.OSBS_LEFT
	}
	if (this.style & CENTER) != 0 {
		bits |= win32.OSBS_CENTER
	}
	if (this.style & RIGHT) != 0 {
		bits |= win32.OSBS_RIGHT
	}
	if (this.style & WRAP) != 0 {
		bits |= win32.OSBS_MULTILINE
	}
	if (this.style & PUSH) != 0 {
		return bits | win32.OSBS_PUSHBUTTON | win32.OSWS_TABSTOP
	}
	if (this.style & CHECK) != 0 {
		return bits | win32.OSBS_CHECKBOX | win32.OSWS_TABSTOP
	}
	if (this.style & RADIO) != 0 {
		return bits | win32.OSBS_RADIOBUTTON
	}
	if (this.style & TOGGLE) != 0 {
		return bits | win32.OSBS_PUSHLIKE | win32.OSBS_CHECKBOX | win32.OSWS_TABSTOP
	}
	if (this.style & COMMAND) != 0 {
		return bits | win32.OSBS_COMMANDLINK | win32.OSWS_TABSTOP
	}
	return bits | win32.OSBS_PUSHBUTTON | win32.OSWS_TABSTOP
}

