func (this *Button) wmNotifyChild_(hdr *win32.NMHDR, wParam int64, lParam int64) *win32.LRESULT {
	switch hdr.Code {
	case win32.OSNM_CUSTOMDRAW:
		var nmcd *win32.NMCUSTOMDRAW = win32.NewNMCUSTOMDRAW()
		win32.OSMoveMemoryOverload44(nmcd, lParam, win32.NMCUSTOMDRAWSizeof)
		switch nmcd.DwDrawStage {
		case win32.OSCDDS_PREPAINT:
			{
				if this.CustomBackgroundDrawing() {
					var pixel int32 = this.background
					if (nmcd.UItemState & win32.OSCDIS_SELECTED) != 0 {
						pixel = this.GetDifferentColor(this.background)
					} else {
						if (nmcd.UItemState & win32.OSCDIS_HOT) != 0 {
							pixel = this.GetSlightlyDifferentColor(this.background)
						}
					}
					if (this.style&TOGGLE) != 0 && this.IsChecked() {
						pixel = this.GetDifferentColor(this.background)
					}
					var brush int64 = win32.OSCreateSolidBrush(pixel)
					var inset int32 = 2
					var radius int32 = 3
					if this.useDarkModeExplorerTheme && win32.OsVersionIS_WIN11_21H2 {
						inset = 1
						radius = 4
					}
					var l int32 = nmcd.Left + inset
					var t int32 = nmcd.Top + inset
					var r int32 = nmcd.Right - inset
					var b int32 = nmcd.Bottom - inset
					if win32.OsVersionIS_WIN11_21H2 {
						l += 1
						t += 1
						win32.OSSaveDC(nmcd.Hdc)
						win32.OSSelectObject(nmcd.Hdc, brush)
						win32.OSSelectObject(nmcd.Hdc, win32.OSGetStockObject(win32.OSNULL_PEN))
						win32.OSRoundRect(nmcd.Hdc, l, t, r, b, radius, radius)
						win32.OSRestoreDC(nmcd.Hdc, -1)
					} else {
						var rect *win32.RECT = win32.NewRECTLeftTopRightBottom(l, t, r, b)
						win32.OSFillRect(nmcd.Hdc, rect, brush)
					}
					win32.OSDeleteObject(brush)
				}
				if this.CustomForegroundDrawing() {
					var radioOrCheckTextPadding int32 = this.GetCheckboxTextOffset(nmcd.Hdc)
					var border int32
					if this.IsRadioOrCheck() {
						border = 0
					} else {
						border = 3
					}
					var left int32 = nmcd.Left + border
					var right int32 = nmcd.Right - border
					if this.image != (nil) {
						var data *GCData = NewGCData()
						data.Device = upcastDisplayToDevice(this.display)
						var gc *GC = this.impl.createNewGC_(nmcd.Hdc, data)
						var margin int32 = this.ComputeLeftMargin()
						var imageBounds *Rectangle = Win32DPIUtilsScaleBounds(this.image.GetBounds(), this.impl.getAutoscalingZoom_(), 100)
						var imageWidth int32 = imageBounds.Width
						var cond197 int32
						if this.IsRadioOrCheck() {
							cond197 = 2 * ButtonMARGIN
						} else {
							cond197 = ButtonMARGIN
						}
						left += (imageWidth + (cond197))
						var cond198 int32
						if this.IsRadioOrCheck() {
							cond198 = radioOrCheckTextPadding
						} else {
							cond198 = 3
						}
						var x int32 = margin + (cond198)
						var y int32 = int32(math.Max(float64(0), float64((nmcd.Bottom-imageBounds.Height)/2)))
						var zoom int32 = this.impl.getAutoscalingZoom_()
						gc.DrawImage(this.image, DPIUtilPixelToPoint(x, zoom), DPIUtilPixelToPoint(y, zoom))
						gc.impl.dispose_()
					}
					var cond199 int32
					if this.IsRadioOrCheck() {
						cond199 = radioOrCheckTextPadding
					} else {
						cond199 = 0
					}
					left += cond199
					var textRect *win32.RECT = win32.NewRECT()
					win32.OSSetRect(textRect, left, nmcd.Top+border, right, nmcd.Bottom-border)
					var buffer []uint16 = utf16.Encode([]rune(this.text))
					var flags int32 = 0
					if (this.style & WRAP) != 0 {
						flags |= win32.OSDT_WORDBREAK
						if !this.IsRadioOrCheck() && this.image != (nil) {
							textRect.Right -= ButtonMARGIN
						}
					} else {
						flags |= win32.OSDT_SINGLELINE
					}
					win32.OSDrawTextHDCLpStringNCountLpRectUFormat(nmcd.Hdc, buffer, int32(len(buffer)), textRect, flags|win32.OSDT_CALCRECT)
					win32.OSOffsetRect(textRect, 0, int32(math.Max(float64(0), float64((nmcd.Bottom-textRect.Bottom-border)/2))))
					if this.image != (nil) {
						flags |= win32.OSDT_LEFT
						if !this.IsRadioOrCheck() {
							win32.OSOffsetRect(textRect, int32(math.Max(float64(ButtonMARGIN), float64((right-textRect.Right)/2+1))), 0)
						}
					} else {
						if (this.style & LEFT) != 0 {
							flags |= win32.OSDT_LEFT
						} else {
							if (this.style & RIGHT) != 0 {
								flags |= win32.OSDT_RIGHT
								win32.OSOffsetRect(textRect, right-textRect.Right, 0)
							} else {
								flags |= win32.OSDT_CENTER
								win32.OSOffsetRect(textRect, (right-textRect.Right)/2, 0)
							}
						}
					}
					win32.OSSetBkMode(nmcd.Hdc, win32.OSTRANSPARENT)
					win32.OSSetTextColor(nmcd.Hdc, this.foreground)
					win32.OSDrawTextHDCLpStringNCountLpRectUFormat(nmcd.Hdc, buffer, int32(len(buffer)), textRect, flags)
					if (nmcd.UItemState & win32.OSCDIS_FOCUS) != 0 {
						var focusRect *win32.RECT = win32.NewRECT()
						if this.IsRadioOrCheck() {
							if jrt.StringLength(this.text) > 0 {
								win32.OSSetRect(focusRect, textRect.Left-1, textRect.Top, int32(math.Min(float64(nmcd.Right), float64(textRect.Right+1))), int32(math.Min(float64(nmcd.Bottom), float64(textRect.Bottom+1))))
							} else {
								win32.OSSetRect(focusRect, nmcd.Left+1+radioOrCheckTextPadding, nmcd.Top, nmcd.Right-2, nmcd.Bottom-1)
							}
						} else {
							win32.OSSetRect(focusRect, nmcd.Left+4, nmcd.Top+4, nmcd.Right-4, nmcd.Bottom-4)
						}
						win32.OSDrawFocusRect(nmcd.Hdc, focusRect)
					}
					return win32.NewLRESULT(int64(win32.OSCDRF_SKIPDEFAULT))
				}
				return win32.NewLRESULT(int64(win32.OSCDRF_DODEFAULT))
			}
		}
		break
	}
	return this.Control.wmNotifyChild_(hdr, wParam, lParam)
}

func (this *Button) wmDrawChild_(wParam int64, lParam int64) *win32.LRESULT {
	if (this.style & ARROW) == 0 {
		return this.Control.wmDrawChild_(wParam, lParam)
	}
	var struct_ *win32.DRAWITEMSTRUCT = win32.NewDRAWITEMSTRUCT()
	win32.OSMoveMemoryOverload33(struct_, lParam, win32.DRAWITEMSTRUCTSizeof)
	var rect *win32.RECT = win32.NewRECT()
	win32.OSSetRect(rect, struct_.Left, struct_.Top, struct_.Right, struct_.Bottom)
	var pressed bool = ((struct_.ItemState & win32.OSODS_SELECTED) != 0)
	var enabled bool = this.impl.getEnabled_()
	var iStateId int32 = ButtonGetThemeStateId(this.style, pressed, enabled)
	win32.OSDrawThemeBackground(this.display.HScrollBarThemeAuto(this.NativeZoom), struct_.HDC, win32.OSSBP_ARROWBTN, iStateId, rect, nil)
	return nil
}

