func ButtonCheckStyle(style int32) int32 {
	var cond200 int32
	if ButtonCOMMAND_LINK {
		cond200 = COMMAND
	} else {
		cond200 = 0
	}
	style = WidgetCheckBits(style, PUSH, ARROW, CHECK, RADIO, TOGGLE, cond200)
	if (style & (PUSH | TOGGLE)) != 0 {
		return WidgetCheckBits(style, CENTER, LEFT, RIGHT, 0, 0, 0)
	}
	if (style & (CHECK | RADIO)) != 0 {
		return WidgetCheckBits(style, LEFT, RIGHT, CENTER, 0, 0, 0)
	}
	if (style & ARROW) != 0 {
		style |= NO_FOCUS
		return WidgetCheckBits(style, UP, DOWN, LEFT, RIGHT, 0, 0)
	}
	return style
}

func ButtonGetThemeStateId(style int32, pressed bool, enabled bool) int32 {
	var direction int32 = style & (UP | DOWN | LEFT | RIGHT)
	if (style & MIRRORED) != 0 {
		if direction == LEFT {
			direction = RIGHT
		} else {
			if direction == RIGHT {
				direction = LEFT
			}
		}
	}
	var hot bool = false
	if win32.OsVersionIS_WIN11_21H2 {
		if !pressed && enabled {
			hot = true
		}
	}
	if hot {
		switch direction {
		case UP:
			return win32.OSABS_UPHOT
		case DOWN:
			return win32.OSABS_DOWNHOT
		case LEFT:
			return win32.OSABS_LEFTHOT
		case RIGHT:
			return win32.OSABS_RIGHTHOT
		}
	}
	if pressed {
		switch direction {
		case UP:
			return win32.OSABS_UPPRESSED
		case DOWN:
			return win32.OSABS_DOWNPRESSED
		case LEFT:
			return win32.OSABS_LEFTPRESSED
		case RIGHT:
			return win32.OSABS_RIGHTPRESSED
		}
	}
	if !enabled {
		switch direction {
		case UP:
			return win32.OSABS_UPDISABLED
		case DOWN:
			return win32.OSABS_DOWNDISABLED
		case LEFT:
			return win32.OSABS_LEFTDISABLED
		case RIGHT:
			return win32.OSABS_RIGHTDISABLED
		}
	}
	switch direction {
	case UP:
		return win32.OSABS_UPNORMAL
	case DOWN:
		return win32.OSABS_DOWNNORMAL
	case LEFT:
		return win32.OSABS_LEFTNORMAL
	case RIGHT:
		return win32.OSABS_RIGHTNORMAL
	}
	return win32.OSABS_LEFTNORMAL
}

